    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] borrowers = new String[n], lenders = new String[n];
        long[] amounts = new long[n];
        for (int i = 0; i < n; i++) {
            borrowers[i] = st.nextToken();
            lenders[i] = st.nextToken();
            amounts[i] = Long.parseLong(st.nextToken());
        }
        System.out.println(String.join(" ", mostIndebted(borrowers, lenders, amounts)));
    }
}
